function soPreview(spec){if(!spec)return`<text x="350" y="205" text-anchor="middle" fill="var(--muted)" font-size="13">בחר כמויות ולחץ “צור Layouts”</text>`;const n=spec.entities.length,centers=Array.from({length:n},(_,i)=>({x:110+i*(480/Math.max(1,n-1)),y:205+48*Math.sin((i-(n-1)/2)*.9)}));let h='';spec.entities.forEach((e,i)=>{const c=centers[i],rot=(i-(n-1)/2)*22;let loop=e.kind==='single'?C.stadiumLoop({x:c.x-55,y:c.y},{x:c.x+55,y:c.y},21,90):e.kind==='double'?C.doubleHippoLoop(c.x,c.y,.35,rot,8):C.figureEightLoop(c.x,c.y,60,32,rot,90);if(e.kind==='single')loop=loop.map(p=>C.rotate(p,c,rot));h+=`<path d="${pathD(loop)}" fill="none" stroke="${[T.storm,T.lightning,T.thunder][i%3]}" stroke-width="4"/>`;for(let v=0;v<e.vehicles;v++){const p=C.pointOnLoop(loop,(v/e.vehicles+.11*i)%1);h+=`<g transform="translate(${p.x} ${p.y}) rotate(${p.heading})"><circle r="10" fill="var(--surface)" stroke="${[T.storm,T.lightning,T.thunder][v%3]}" stroke-width="2"/><path d="M0-9 6 7 0 4-6 7Z" fill="${[T.storm,T.lightning,T.thunder][v%3]}"/></g>`}});spec.relations.forEach((r,i)=>h+=relationBadge((centers[i].x+centers[i+1].x)/2,(centers[i].y+centers[i+1].y)/2-48,r==='same'?'זהה':r==='opposite'?'הפוך':'מעורב'));return h}
