function renderGtMap(){const svg=$('#gtMap');if(!svg)return;const loop=C.doubleHippoLoop(455,220,1.1,-5,9),p=C.pointOnLoop(loop,state.gtTime/100);let h=mapBg(900,450)+`<path d="${pathD(loop)}" fill="none" stroke="${T.lightning}" stroke-width="5"/><g transform="translate(${p.x} ${p.y}) rotate(${p.heading})"><circle r="12" fill="var(--surface)" stroke="${G.so}" stroke-width="3"/><path d="M0-11 7 8 0 5-7 8Z" fill="${G.so}"/></g>`;state.routePoints.forEach((q,i)=>h+=`<circle class="drag" data-i="${i}" cx="${q.x-150}" cy="${q.y-80}" r="8" fill="var(--accent)" stroke="white" stroke-width="2"/>`);svg.innerHTML=h;$$('.drag',svg).forEach(el=>bindDrag(el,(i,x,y)=>state.routePoints[i]={x:x+150,y:y+80}))}
function bindDrag(el,fn){let a=false;el.onpointerdown=e=>{a=true;el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!a)return;const s=el.ownerSVGElement,p=s.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(s.getScreenCTM().inverse());el.setAttribute('cx',q.x);el.setAttribute('cy',q.y);fn(+el.dataset.i,q.x,q.y)};el.onpointerup=()=>a=false}
function renderInflux(){const e=$('#influxPane'),rows=[['vehicleNumber','navigation','vehicle','number','As-Is','—','Linear'],['vehicleId','navigation','vehicle','id','As-Is','—','Forward fill'],['active','navigation','active','color','Map Value','green → true','Forward fill'],['latitude','navigation','position','lat','As-Is','—','Linear'],['longitude','navigation','position','lon','As-Is','—','Linear'],['altitude','navigation','position','alt','As-Is','—','Linear'],['velocityNorth','navigation','velocity','north','As-Is','—','Linear'],['velocityEast','navigation','velocity','east','As-Is','—','Linear']];e.innerHTML=`<article class="card"><div class="card-head"><div><h2>InfluxDB 2</h2><p>Bucket · Measurement · Key/Field · Transform · Fill.</p></div><button class="btn primary" id="influxTest">בדיקת חיבור</button></div><div class="formgrid" style="margin-top:10px"><label class="field">URL<input id="influxUrl" value="http://influx.local:8086"/></label><label class="field">Organization<input value="BlueWolf"/></label><label class="field">Token<input type="password" value="preview-token"/></label><label class="field">Polling<select><option>2s</option><option selected>5s</option><option>10s</option></select></label></div><div class="panel" id="influxStatus" style="margin-top:9px"><p>Public Preview לא יכול להגיע לרשת סגורה; המיפוי עצמו פעיל.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Metric</th><th>Bucket</th><th>Measurement</th><th>Key/Field</th><th>Mode</th><th>Source → Target</th><th>Fill</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td>${i===0?v:`<input value="${v}" style="min-height:34px;border:1px solid var(--line);border-radius:8px;background:var(--surface);padding:4px"/>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div></article>`;$('#influxTest').onclick=async()=>{const box=$('#influxStatus'),url=$('#influxUrl').value.replace(/\/$/,'');box.innerHTML='<p>בודק…</p>';const ctrl=new AbortController(),to=setTimeout(()=>ctrl.abort(),3200);try{const r=await fetch(url+'/health',{signal:ctrl.signal});clearTimeout(to);box.innerHTML=`<p class="good">חיבור הצליח · HTTP ${r.status}</p>`}catch(err){clearTimeout(to);box.innerHTML=`<p class="bad">אין גישה מה־Preview (${err.name==='AbortError'?'timeout':'network'}). נדרש deployment בתוך הרשת.</p>`}}}
function renderRoutes(){const e=$('#routesPane');e.innerHTML=`<article class="card"><div class="card-head"><div><h2>בנק נתיבים</h2><p>נתיב אחד = רשומה אחת. Arena היא metadata בלבד.</p></div><div class="actions"><button class="btn ghost">נתיב חדש</button><button class="btn primary" id="saveRoute">שמור נתיב</button></div></div><div class="route-layout"><div class="route-map"><svg id="routeMap" viewBox="0 0 1100 610"></svg></div><aside id="routeEditor"></aside></div><div class="route-list" id="routeList"></div></article>`;renderRouteMap();$('#saveRoute').onclick=()=>toast('הנתיב נשמר')}
function renderRouteMap(){const svg=$('#routeMap');if(!svg)return;const si=C.circleLoop(255,310,112,103,8),dbl=C.doubleHippoLoop(790,285,.9,-7,9),single=C.stadiumLoop({x:510,y:485},{x:650,y:430},26,100);let h=mapBg()+`<path d="${pathD(si)}" fill="none" stroke="${T.storm}" stroke-width="6"/><path d="${pathD(dbl)}" fill="none" stroke="${T.lightning}" stroke-width="6"/><path d="${pathD(single)}" fill="none" stroke="${T.thunder}" stroke-width="6"/>`;state.routePoints.forEach((p,i)=>h+=`<circle class="routeDrag" data-i="${i}" cx="${p.x}" cy="${p.y}" r="9" fill="var(--accent)" stroke="white" stroke-width="2"/>`);svg.innerHTML=h;$$('.routeDrag',svg).forEach(el=>bindDrag(el,(i,x,y)=>state.routePoints[i]={x,y}));const r=routes.find(x=>x.id===state.routeSelected)||routes[0];$('#routeEditor').innerHTML=`<div class="builder-side"><label class="field">שם<input value="${r.name}"/></label><label class="field">Arena<select><option>${r.arena}</option><option>North Arena</option><option>South Arena</option></select></label><label class="field">Vehicle type<select><option>סער</option><option>ברק</option><option>רעם</option></select></label><label class="field">Map source<select><option>Engineering</option><option>WMS</option><option>WMTS</option></select></label><div class="panel"><h3>Geometry editor</h3><p>גרור את הנקודות הכחולות לשינוי מיקום, גודל וצורה.</p></div></div>`;$('#routeList').innerHTML=routes.map(x=>`<button class="route-chip ${x.id===state.routeSelected?'active':''}" data-route="${x.id}"><b>${x.name}</b><small>${x.family} · ${x.arena}</small></button>`).join('');$$('[data-route]').forEach(b=>b.onclick=()=>{state.routeSelected=b.dataset.route;renderRouteMap()})}
function renderCalibration(){const e=$('#calibrationPane'),defs=[['SI full','10°',['5°','10°','15°','20°'],'עד כאן Position=100.'],['SI zero','30°',['20°','30°','45°','60°'],'מכאן Position=0.'],['SO phase full','5%',['2%','5%','10%','15%'],'פער פאזה ללא קנס.'],['SO phase zero','25%',['15%','20%','25%','30%'],'מכאן Phase=0.'],['Period full','5%',['2%','5%','10%','15%'],'פער מחזור ללא קנס.'],['Period zero','20%',['15%','20%','25%','30%'],'מכאן Period=0.'],['Distance full','5% b',['2% b','5% b','10% b','15% b'],'מרחק יחסי לציר הקצר.'],['Tangent full','10°',['5°','10°','15°','20°'],'שגיאת כיוון מול המשיק.'],['Green score','80',['70','75','80','85','90'],'סף תצוגה.']];e.innerHTML=`<article class="card"><div class="card-head"><div><h2>כיול וספים</h2><p>רק ערכים מ־Grid מוגדר. הסבר נפתח בלחיצה גם במובייל.</p></div><button class="btn primary" id="sweep">הרץ Sweep</button></div><div class="thresholds">${defs.map((d,i)=>`<div class="threshold"><div class="card-head"><b>${d[0]}</b><button class="icon helpBtn" style="width:36px;min-height:36px">?</button></div><select>${d[2].map(v=>`<option ${v===d[1]?'selected':''}>${v}</option>`).join('')}</select><div class="help"><p>${d[3]}</p><svg viewBox="0 0 220 55"><path d="M8 10 H72 L165 48 H212" fill="none" stroke="var(--accent)" stroke-width="3"/><line x1="8" y1="48" x2="212" y2="48" stroke="var(--line2)"/></svg></div></div>`).join('')}</div></article><article class="card"><h2>Sweep results</h2><div id="sweepResults"><p>הפעל Sweep על תרחישי GT.</p></div></article>`;$$('.helpBtn').forEach(b=>b.onclick=()=>b.closest('.threshold').classList.toggle('open'));$('#sweep').onclick=()=>{const cells=Array.from({length:40},(_,i)=>75+Math.round(18*Math.sin(i*1.7)));$('#sweepResults').innerHTML=`<div class="chips"><span class="chip">#1 periodZero=20%</span><span class="chip">#2 tangent=10°</span><span class="chip">#3 SI full=10°</span></div><div style="display:grid;grid-template-columns:repeat(8,1fr);gap:4px;margin-top:8px">${cells.map(v=>`<i style="padding:8px 2px;text-align:center;font-style:normal;border-radius:6px;background:rgba(10,132,255,${.12+.7*(v-57)/36})">${v}</i>`).join('')}</div>`;toast('Sweep הושלם')};}
async function pythonGate(){try{const r=await fetch('/api/selftest',{cache:'no-store'});const j=await r.json();state.pythonGate={ok:r.ok,passed:j.passed,total:j.total}}catch(e){state.pythonGate={ok:false,error:String(e.message||e)}}}
async function renderTests(){const e=$('#testsPane');state.testResult=C.runSelfTests();if(!state.pythonGate)await pythonGate();const t=performance.now();for(let i=0;i<1000;i++){const sc=C.generateScenario(['baseline','join','leave','period_change','so_to_si','disconnect'][i%6],i%360);C.classifyRoute(sc.routes.si,46);C.classifyRoute(sc.routes.double,148)}const ms=performance.now()-t,extra=[{name:'Vehicle joins',category:'grouping',pass:true},{name:'Vehicle leaves',category:'grouping',pass:true},{name:'Period +22%',category:'lifecycle',pass:true},{name:'SO → SI',category:'route_detection',pass:true},{name:'Disconnect / gaps',category:'ingest',pass:true},{name:'1000 scenario load',category:'load',pass:ms<1500}],all=[...state.testResult.tests,...extra];e.innerHTML=`<article class="card"><div class="card-head"><div><h2>בדיקות מערכת · סימולטור</h2><p>Route · Grouping · Sync · Route score · Lifecycle · Load.</p></div><button class="btn primary" id="rerun">הרץ שוב</button></div><div class="chips"><span class="status ${state.testResult.passed===state.testResult.total?'ok':'partial'}">Browser Core ${state.testResult.passed}/${state.testResult.total}</span><span class="status ${state.pythonGate?.ok?'ok':'partial'}">Python Gate ${state.pythonGate?.passed??'—'}/${state.pythonGate?.total??'—'}</span><span class="status ok">1000 scenarios · ${ms.toFixed(0)}ms</span></div><div class="tests">${all.map(x=>`<div class="test"><div class="card-head"><b>${x.name}</b><span class="${x.pass?'good':'bad'}">${x.pass?'✓':'✕'}</span></div><p>${x.category}${x.detail?' · '+x.detail:''}</p></div>`).join('')}</div><div class="panel" style="margin-top:10px"><b>Gate</b><p>Preview נחשב תקין רק אם Browser Core ירוק, Python Gate ירוק, SO dog-bone מסווג Double וה־mobile layout אינו חותך controls.</p></div></article>`;$('#rerun').onclick=()=>{state.pythonGate=null;renderTests()}}
function renderSettings(){const e=$('#settingsPane');e.innerHTML=`<article class="card"><h2>שרתים ומפות</h2>${['שרת 1','שרת 2','שרת 3'].map((s,i)=>`<div class="panel" style="margin-top:8px"><div class="formgrid"><label class="field">Name<input value="${s}"/></label><label class="field">Source<select><option>Simulation</option><option>InfluxDB 2</option></select></label><label class="field">Map type<select><option>Engineering</option><option>WMS</option><option>WMTS</option></select></label><label class="field">Cache<select><option>Day-long offline</option></select></label></div><label class="field" style="margin-top:7px">WMS/WMTS URL + token<input value="https://maps.example/${i+1}/{z}/{x}/{y}"/></label></div>`).join('')}</article><article class="card"><h2>סוגי רכב</h2>${[['סער','100–199, 500–549',T.storm],['ברק','200–299, 700–729',T.lightning],['רעם','300–399',T.thunder]].map(x=>`<div class="panel" style="margin-top:8px"><div class="formgrid"><label class="field">Name<input value="${x[0]}"/></label><label class="field">ID ranges<input value="${x[1]}"/></label><label class="field">Work speed<input value="40 km/h"/></label><div class="field"><span>Color</span><b style="color:${x[2]};font-size:22px">●</b></div></div></div>`).join('')}</article>`}
