function openTemplateModal(){const isSi=state.selectedGroup==='si',base=isSi?92:82,expected=base+(isSi?2:5),preview=isSi?`<svg viewBox="0 0 700 270"><rect width="700" height="270" fill="var(--map)"/><g transform="translate(0 -70)">${siPreview()}</g></svg>`:`<svg viewBox="0 0 700 270"><rect width="700" height="270" fill="var(--map)"/>${soPreview(state.soSelection||{entities:[{kind:'single',vehicles:1},{kind:'double',vehicles:2},{kind:'single',vehicles:1}],relations:['same','mixed']})}</svg>`;$('#templateModalBody').innerHTML=`<div class="expected"><div><span>Total צפוי</span><b>${expected}</b></div><div><span>Sync צפוי</span><b>${expected+2}</b></div><div><span>Route צפוי</span><b>${expected-3}</b></div></div><div class="preview" style="margin-top:8px">${preview}</div><div class="formgrid" style="margin-top:9px"><label class="field">Template<select><option>${isSi?'SI 120°':'Single—Double—Single'}</option><option>${isSi?'SI 90°':'Double—Single'}</option></select></label><label class="field">Apply<select id="scope"><option value="now">מעכשיו</option><option value="event">מתחילת האירוע הנוכחי</option></select></label></div><button class="btn primary" id="applyTpl" style="width:100%;margin-top:10px">החל וחישוב מחדש</button>`;$('#templateModal').classList.add('open');$('#applyTpl').onclick=()=>{$('#templateModal').classList.remove('open');toast($('#scope').value==='event'?'הוחל מתחילת האירוע והציונים חושבו מחדש':'הוחל מעכשיו')}}
let last=performance.now();function tick(now){if(now-last>220){last=now;if(state.playing&&state.tab==='operator'){state.time=(state.time+.15)%300;const s=$('#timeSlider');if(s)s.value=state.time;const l=$('#timeLabel');if(l)l.textContent=fmtTime(state.time);renderLiveMap()}if(state.gtPlaying&&state.tab==='developer'){state.gtTime=(state.gtTime+.22)%100;const s=$('#gtTime');if(s)s.value=state.gtTime;const l=$('#gtLabel');if(l)l.textContent='00:'+String(Math.round(state.gtTime*.6)).padStart(2,'0');renderGtMap()}}requestAnimationFrame(tick)}
shell();pythonGate().then(()=>{if(state.tab==='developer'&&state.dev==='tests')renderTests()});requestAnimationFrame(tick);
